pub fn spiral(m: List[List[Int]]) -> List[Int] {
  let empty_row: List[Int] = []
  let rows = m.len()
  let cols = m.get_or(0, empty_row).len()
  var out: List[Int] = []
  var top = 0
  var bottom = rows - 1
  var left = 0
  var right = cols - 1
  while top <= bottom and left <= right {
    for c in range(left, right + 1) {
      out = out.push(m.get_or(top, empty_row).get_or(c, 0))
    }
    top = top + 1
    for r in range(top, bottom + 1) {
      out = out.push(m.get_or(r, empty_row).get_or(right, 0))
    }
    right = right - 1
    if top <= bottom {
      for k in range(0, right - left + 1) {
        out = out.push(m.get_or(bottom, empty_row).get_or(right - k, 0))
      }
      bottom = bottom - 1
    }
    if left <= right {
      for k in range(0, bottom - top + 1) {
        out = out.push(m.get_or(bottom - k, empty_row).get_or(left, 0))
      }
      left = left + 1
    }
  }
  return out
}
